def create_effective_prompt(task, role, context, output_format):
    prompt = f"""Role: {role}

Task: {task}

Context: {context}

Output Format: {output_format}"""
    return prompt

# Example usage:
prompt = create_effective_prompt(
    task="Analyze customer feedback for product improvement",
    role="Customer Experience Analyst",
    context="We received 500 customer reviews about our new smartphone model",
    output_format="Provide a summary of key findings, top 3 issues, and recommendations in bullet points"
)
print(prompt)
